export const glossary=[
 {id:'se11',term:'SE11',aliases:['SE11'],meaning:'DB 테이블·구조체·필드 타입 같은 데이터 정의를 만들고 확인하는 도구예요. Z로 시작하는 실습 테이블은 시스템에 없으면 먼저 만들어야 해요.',where:'SAP GUI 명령창에 /nSE11 → 객체 종류와 이름 입력',example:'ZC505T0042 같은 사용자 테이블은 문서의 필드·키·타입 표를 보고 생성해요. 소스 코드만 복사하면 테이블이 자동으로 생기지는 않아요.'},
 {id:'screen',term:'Screen',aliases:['Screen Painter','Screen','Dynpro'],meaning:'SAP GUI에서 실제로 표시되는 한 장의 화면이에요. 0100·0200은 화면을 구분하는 번호예요.',where:'SE80 또는 SE51 → 프로그램의 화면 목록에서 만들고 편집해요.',example:'화면 0100을 만든 뒤 입력칸·컨테이너를 배치해요.'},
 {id:'normal',term:'Normal Screen',aliases:['Normal Screen'],meaning:'독립적으로 표시하는 일반 화면이에요. 다른 화면 안에 끼워 넣는 Subscreen과 구분해요.',where:'SE80/SE51 → 화면 속성 → 화면 유형',example:'일반 조회 화면은 보통 Normal Screen으로 만들어요.'},
 {id:'next',term:'Next Screen',aliases:['Next Screen'],meaning:'현재 화면 처리가 끝난 뒤 이어서 표시할 화면 번호예요. 코드의 화면 이동 명령에 따라 바뀔 수도 있어요.',where:'SE80/SE51 → 화면 속성 → 다음 화면',example:'0100 화면의 Next Screen이 0100이면 기본적으로 같은 화면을 이어서 표시해요.'},
 {id:'flow',term:'Flow Logic',aliases:['Flow Logic'],meaning:'이 화면을 보여주기 전과 입력을 받은 뒤, 어떤 MODULE을 실행할지 적는 연결표예요. 일반 ABAP 프로그램 코드와 붙이는 위치가 달라요.',where:'SE80/SE51 → 해당 화면 → Flow Logic 탭',example:'PBO에는 화면 준비 MODULE, PAI에는 버튼 처리 MODULE을 연결해요.'},
 {id:'pbo',term:'PBO',aliases:['PBO','PROCESS BEFORE OUTPUT'],meaning:'화면이 보이기 직전에 실행돼요. 제목·버튼·ALV를 준비하는 위치예요. 화면이 다시 표시될 때도 실행될 수 있어요.',where:'화면의 Flow Logic → PROCESS BEFORE OUTPUT.',example:'제목 설정 → 컨테이너 최초 생성 → ALV 표시'},
 {id:'pai',term:'PAI',aliases:['PAI','PROCESS AFTER INPUT'],meaning:'사용자가 Enter나 버튼으로 입력을 전달했을 때 실행돼요. 눌린 버튼을 확인하고 조회·저장·종료 등을 처리해요.',where:'화면의 Flow Logic → PROCESS AFTER INPUT.',example:'저장 버튼 → OK Code 확인 → 저장 FORM 실행'},
 {id:'guistatus',term:'GUI Status',aliases:['GUI Status','PF-STATUS'],meaning:'화면에 표시할 메뉴·툴바·기능키의 묶음이에요. S0100 같은 이름은 이 묶음의 이름이에요.',where:'SE41 → Status 작성, 프로그램에서는 SET PF-STATUS로 사용',example:'조회·저장·뒤로가기 버튼을 S0100에 등록해요.'},
 {id:'function',term:'Function Code',aliases:['Function Code'],meaning:'버튼을 눌렀을 때 프로그램으로 전달되는 명령 이름이에요. 버튼에 보이는 글자와 코드에서 비교하는 이름은 다를 수 있어요.',where:'SE41의 버튼 속성 → Function Code',example:'화면 글자는 저장, 전달하는 명령은 SAVE로 정할 수 있어요.'},
 {id:'functiontype',term:'Function Type',aliases:['Function Type'],meaning:'버튼 명령을 어떤 방식으로 처리할지 정하는 속성이에요. 종료 명령에 E를 지정하면 AT EXIT-COMMAND MODULE로 처리할 수 있어요.',where:'SE41 → 해당 Function Code의 기능 유형',example:'BACK·EXIT·CANC를 E로 설정했다면 Flow Logic에도 AT EXIT-COMMAND를 연결해요.'},
 {id:'okcode',term:'OK Code',aliases:['OK Code','OKCODE','GV_OKCODE'],meaning:'누른 버튼의 Function Code를 담는 화면 필드와 ABAP 변수예요. 이 값을 CASE로 확인해 작업을 나눠요.',where:'화면 속성의 OK Code 필드와 TOP의 변수 선언을 같은 이름으로 연결',example:"GV_OKCODE = 'SAVE'이면 저장 FORM을 호출해요."},
 {id:'title',term:'TITLEBAR',aliases:['TITLEBAR','Text Symbol'],meaning:'TITLEBAR는 화면 제목, Text Symbol은 프로그램에서 다시 사용하는 문구예요. T0100과 TEXT-T01은 서로 다른 객체예요.',where:'화면 제목은 SE41/SE80, Text Symbol은 SE38의 텍스트 요소',example:"SET TITLEBAR 'T0100'은 등록한 화면 제목을 표시해요."},
 {id:'module',term:'MODULE',aliases:['MODULE'],meaning:'화면 Flow Logic에서 호출하는 ABAP 처리 단위예요. OUTPUT은 화면 표시 전, INPUT은 입력 후 처리와 연결돼요.',where:'Flow Logic의 MODULE 이름과 프로그램의 MODULE ... ENDMODULE 이름을 맞춰요.',example:'MODULE status_0100 OUTPUT 안에서 제목과 버튼을 준비해요.'},
 {id:'top',term:'TOP',aliases:['TOP'],meaning:'전역 변수·구조·내부 테이블·객체 참조를 선언해 모아두는 구간이나 Include 이름이에요.',where:'프로그램 앞부분 또는 프로그램명_TOP Include',example:'GT_DATA, GS_DATA, GCL_GRID를 먼저 선언해요.'},
 {id:'include',term:'INCLUDE',aliases:['INCLUDE'],meaning:'다른 소스 파일의 코드를 이 위치에 연결하는 문장이에요. TOP·C01·F01 등으로 파일을 나누어 관리할 때 써요.',where:'메인 프로그램의 INCLUDE 이름과 실제 Include 객체를 연결',example:'통합본은 Include 내용을 이미 펼친 코드라, 원본 Include를 다시 붙이면 선언이 중복될 수 있어요.'},
 {id:'form',term:'FORM / PERFORM',aliases:['PERFORM','FORM'],meaning:'FORM은 이름 붙인 처리 묶음이고, PERFORM은 그 처리를 호출하는 문장이에요.',where:'프로그램의 FORM ... ENDFORM 또는 F01 Include',example:'PERFORM get_data. → FORM get_data 안의 조회 코드 실행'},
 {id:'alv',term:'ALV',aliases:['ALV'],meaning:'조회한 데이터를 표로 보여주는 SAP의 목록 도구예요. 열 설정·정렬·선택·편집 같은 기능을 붙일 수 있어요.',where:'표시용 데이터 + 컨테이너 + Grid 객체 + 열 설정을 준비',example:'GT_DATA의 행을 GCL_GRID로 화면에 표시해요.'},
 {id:'container',term:'Container',aliases:['Container','Custom Control'],meaning:'ALV나 편집기 같은 화면 도구를 담는 영역이에요. Custom Control은 Screen Painter에서 직접 그려 이름을 붙이는 영역이에요.',where:'SE80/SE51 화면 배치와 컨테이너 생성 코드를 연결',example:"화면의 CC_ALV 이름과 코드의 CONTAINER_NAME을 맞춰요."},
 {id:'docking',term:'Docking',aliases:['Docking'],meaning:'화면의 가장자리에 붙여 만드는 컨테이너 방식이에요. Custom Control을 직접 그리는 방식과 준비 과정이 달라요.',where:'CL_GUI_DOCKING_CONTAINER 생성 코드',example:'예제가 Docking 방식이면 화면에 CC_ALV를 별도로 그리지 않을 수 있어요.'},
 {id:'splitter',term:'Splitter',aliases:['Splitter'],meaning:'한 컨테이너를 여러 칸으로 나누는 도구예요. 각 칸에 서로 다른 ALV를 넣을 수 있어요.',where:'CL_GUI_SPLITTER_CONTAINER → GET_CONTAINER로 각 칸 가져오기',example:'1행 2열로 나누면 왼쪽 목록과 오른쪽 상세 표를 만들 수 있어요.'},
 {id:'grid',term:'Grid',aliases:['Grid'],meaning:'컨테이너 안에서 데이터를 실제 표로 보여주는 객체예요. 컨테이너는 자리, Grid는 그 자리에 놓는 표라고 보면 돼요.',where:'CL_GUI_ALV_GRID 객체를 컨테이너에 연결',example:'한 컨테이너에 Grid 객체를 만들어 GT_DATA를 전달해요.'},
 {id:'fcat',term:'FCAT',aliases:['FCAT','Field Catalog','Fieldcatalog'],meaning:'표의 각 열을 어떻게 표시할지 적는 설정 목록이에요. 필드명·제목·편집 가능 여부·참조 타입 등을 정해요.',where:'LVC_T_FCAT / LVC_S_FCAT',example:'CARRID 열 제목을 항공사 코드로 표시하고 키 열로 설정해요.'},
 {id:'layout',term:'Layout',aliases:['Layout'],meaning:'ALV 표 전체의 모양과 동작 설정이에요. 줄무늬·열 너비·선택 방식 등을 정해요. 저장된 사용자 배치 Variant와는 구분해요.',where:'LVC_S_LAYO → SET_TABLE_FOR_FIRST_DISPLAY',example:"ZEBRA = 'X'이면 행 배경을 번갈아 표시해요."},
 {id:'handler',term:'SET HANDLER',aliases:['SET HANDLER','Handler'],meaning:'어떤 객체에서 이벤트가 나면 어느 메서드를 실행할지 연결하는 문장이에요.',where:'이벤트 클래스 선언·구현 후 ALV 생성 구간에서 등록',example:'더블클릭 이벤트를 handle_double_click 메서드에 연결해요.'},
 {id:'ddic',term:'DDIC',aliases:['DDIC'],meaning:'테이블·구조·도메인·데이터 엘리먼트 같은 데이터 정의를 모아두는 ABAP Dictionary예요.',where:'주로 SE11에서 확인·생성',example:'코드에 Z 테이블이 있으면 먼저 그 테이블과 필드 정의가 필요해요.'},
 {id:'itab',term:'ITAB',aliases:['ITAB','Internal Table'],meaning:'프로그램 실행 중 여러 행을 담는 메모리 안의 표예요. DB 테이블과 달리, 값을 바꿨다고 자동으로 DB에 저장되지는 않아요.',where:'DATA ... TYPE TABLE OF ... / GT_* 변수',example:'DB 조회 → GT_DATA에 담기 → ALV 표시'},
 {id:'scarr',term:'SCARR / SPFLI',aliases:['SCARR','SPFLI'],meaning:'학습 예제에 자주 나오는 표준 항공 데이터 테이블이에요. SCARR는 항공사, SPFLI는 항공 노선 정보를 다뤄요.',where:'SE11에서 필드, SE16N에서 현재 데이터 확인',example:'항공사 하나를 선택해서 그 항공사의 노선을 조회하는 예제에 사용해요.'},
 {id:'bdc',term:'BDC',aliases:['BDC','BDCDATA','SHDB'],meaning:'SAP 화면에 값을 순서대로 넣고 버튼을 누르는 과정을 코드로 실행하는 방식이에요. SHDB로 녹화한 화면 순서가 바탕이에요.',where:'SHDB 녹화 → BDCDATA 작성 → CALL TRANSACTION',example:'FB01 헤더 입력 → 항목 입력 → 저장 순서를 재현해요.'},
 {id:'se38',term:'SE38',aliases:['SE38'],meaning:'ABAP 실행 프로그램 소스를 만들고 편집·실행하는 도구예요.',where:'SAP GUI 명령창에 /nSE38',example:'프로그램 전체 코드는 프로그램 편집기에 붙여요.'},
 {id:'se80',term:'SE80 / SE51',aliases:['SE80','SE51'],meaning:'SE80은 개발 객체를 모아 관리하는 도구, SE51은 화면을 만들고 편집하는 도구예요.',where:'프로그램 아래의 화면 → 속성·배치·Flow Logic',example:'Flow Logic은 프로그램 편집기가 아니라 해당 화면의 탭에 붙여요.'},
 {id:'se41',term:'SE41',aliases:['SE41'],meaning:'메뉴·버튼·기능키와 화면 제목을 만드는 도구예요.',where:'SAP GUI 명령창에 /nSE41',example:'프로그램 이름을 넣고 S0100 Status와 T0100 제목을 만들어요.'}
];
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const terms=glossary.flatMap(g=>g.aliases.map(a=>({alias:a,id:g.id}))).sort((a,b)=>b.alias.length-a.alias.length);
const re=new RegExp('(^|[^A-Za-z0-9_])('+terms.map(t=>t.alias.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?=$|[^A-Za-z0-9_])','gi');
export function explainTerms(html){return html.split(/(<[^>]*>)/g).map((part,i)=>i%2?part:part.replace(re,(_,before,term)=>{const g=terms.find(t=>t.alias.toLowerCase()===term.toLowerCase());return before+`<button class="term-help" data-term="${g.id}" aria-label="${escape(term)} 뜻 보기">${escape(term)}<sup>?</sup></button>`})).join('');}
export function termPanel(id){const g=glossary.find(t=>t.id===id);if(!g)return '';return `<header><span>용어 풀이</span><button data-term-close aria-label="용어 풀이 닫기">닫기 ×</button></header><h2>${escape(g.term)}</h2><p>${escape(g.meaning)}</p><h3>어디서 설정하나요?</h3><p>${escape(g.where)}</p><h3>예를 들면</h3><p>${escape(g.example)}</p>`;}
export function documentGuide(d){const text=d.body,title=d.title;const isScreen=d.category==='화면·조회조건'||d.recipe&&/CALL SCREEN|PROCESS BEFORE OUTPUT/i.test(text);if(!isScreen)return '';const customTables=[...new Set([...text.matchAll(/SE11\s+(Z[\w/]+)/gi)].map(m=>m[1]))];const program=text.match(/^\s*(?:REPORT|PROGRAM)\s+([\w/]+)/im)?.[1],screen=text.match(/CALL SCREEN\s+['"]?(\d{4})/i)?.[1],status=text.match(/SET PF-STATUS\s+['"]([^'"]+)/i)?.[1],bar=text.match(/SET TITLEBAR\s+['"]([^'"]+)/i)?.[1];return `<section class="plain-guide"><div class="plain-guide-title">이 예제는 이렇게 나눠서 따라가세요</div><p>프로그램 코드와 화면 설정은 붙이는 곳이 달라요. 먼저 아래 세 곳을 구분하면 문서가 쉬워져요.</p>${customTables.length?`<div class="plain-table-prerequisite"><strong>이 예제는 사용자 테이블이 먼저 필요해요</strong><p>${customTables.map(escape).join(', ')} 테이블을 <button data-term="se11">SE11에서 만들기</button>로 먼저 준비해요. 아래 원문의 필드·키·타입 표를 따르세요.</p></div>`:''}<ol><li><strong>프로그램 소스</strong><span><button data-term="se38">SE38 뜻 보기</button>에서 ${program?`<code>${escape(program)}</code> 프로그램을 만들고`: '프로그램을 만들고'} 선언·MODULE·FORM을 넣어요.</span></li><li><strong>화면과 연결 순서</strong><span><button data-term="se80">SE80·SE51 뜻 보기</button>에서 ${screen?`<code>${screen}</code> 화면을 만들고`:'해당 화면을 만들고'} 화면 배치와 Flow Logic을 설정해요.</span></li><li><strong>버튼·메뉴·제목</strong><span><button data-term="se41">SE41 뜻 보기</button>에서 ${status?`<code>${escape(status)}</code> 버튼 묶음`:'GUI Status'}${bar?`과 <code>${escape(bar)}</code> 제목`:''}을 준비해요.</span></li></ol><p class="plain-guide-hint">점선 밑줄이 있는 용어를 누르면 뜻과 설정 위치가 나와요. 정확한 객체 이름과 화면 번호는 아래 원문을 따르세요.</p></section>`;}

export function documentTitle(d){const title=String(d.title).replace(/^[^\p{L}\p{N}]+/u,'').replace(/^\d{1,2}\s+/,'');if(/기초 조회화면/.test(title))return '첫 조회 화면 만들기 — 항공사 목록';if(/^기초 CRUD 화면/.test(title))return '입력한 데이터를 생성·수정·삭제하는 화면';if(/^기본 ALV/.test(title))return '화면 안에 표 넣기 — 기본 ALV';if(/^Splitter 화면/.test(title))return '화면을 나누고 두 목록 연결하기';if(/^ALV 트리.*왼쪽/.test(title))return '왼쪽 트리를 선택해 오른쪽 상세 표 바꾸기';if(/^화면 필드 동적 제어/.test(title))return '버튼·조건에 따라 입력칸을 잠그거나 열기';return title;}
